import { IDNAError } from './errors.mjs';
import { toChars } from './unicode.mjs';

const BASE = 36;
const T_MIN = 1;
const T_MAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';
const MAX_INT = 0x7fffffff;

function adapt(delta, numPoints, firstTime) {
  let value = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  value += Math.floor(value / numPoints);

  let k = 0;
  while (value > (((BASE - T_MIN) * T_MAX) >> 1)) {
    value = Math.floor(value / (BASE - T_MIN));
    k += BASE;
  }

  return k + Math.floor(((BASE - T_MIN + 1) * value) / (value + SKEW));
}

function basicToDigit(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) {
    return codePoint - 0x16;
  }
  if (codePoint >= 0x61 && codePoint <= 0x7a) {
    return codePoint - 0x61;
  }
  return BASE;
}

function digitToBasic(digit) {
  if (digit < 26) {
    return String.fromCharCode(0x61 + digit);
  }
  return String.fromCharCode(0x16 + digit);
}

export function encodePunycode(input) {
  const codePoints = toChars(input).map((char) => char.codePointAt(0));
  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  let handled = 0;
  const output = [];

  for (const codePoint of codePoints) {
    if (codePoint < 0x80) {
      output.push(String.fromCodePoint(codePoint));
      handled += 1;
    }
  }

  const basicLength = handled;
  if (basicLength > 0) {
    output.push(DELIMITER);
  }

  while (handled < codePoints.length) {
    let nextCodePoint = MAX_INT;
    for (const codePoint of codePoints) {
      if (codePoint >= n && codePoint < nextCodePoint) {
        nextCodePoint = codePoint;
      }
    }

    delta += (nextCodePoint - n) * (handled + 1);
    n = nextCodePoint;

    for (const codePoint of codePoints) {
      if (codePoint < n) {
        delta += 1;
      }

      if (codePoint !== n) {
        continue;
      }

      let q = delta;
      for (let k = BASE; ; k += BASE) {
        const t = k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;
        if (q < t) {
          break;
        }
        output.push(digitToBasic(t + ((q - t) % (BASE - t))));
        q = Math.floor((q - t) / (BASE - t));
      }

      output.push(digitToBasic(q));
      bias = adapt(delta, handled + 1, handled === basicLength);
      delta = 0;
      handled += 1;
    }

    delta += 1;
    n += 1;
  }

  return output.join('');
}

export function decodePunycode(input) {
  const source = input.toLowerCase();
  if (source.length === 0) {
    throw new IDNAError('Malformed A-label, no Punycode eligible content found');
  }
  if (!/^[a-z0-9-]+$/.test(source)) {
    throw new IDNAError('Invalid A-label');
  }

  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  const lastDelimiter = source.lastIndexOf(DELIMITER);
  let index = 0;

  if (lastDelimiter >= 0) {
    for (; index < lastDelimiter; index += 1) {
      const codePoint = source.charCodeAt(index);
      if (codePoint >= 0x80) {
        throw new IDNAError('Invalid A-label');
      }
      output.push(codePoint);
    }
    index += 1;
  }

  while (index < source.length) {
    const oldI = i;
    let w = 1;

    for (let k = BASE; ; k += BASE) {
      if (index >= source.length) {
        throw new IDNAError('Invalid A-label');
      }

      const digit = basicToDigit(source.charCodeAt(index));
      index += 1;

      if (digit >= BASE) {
        throw new IDNAError('Invalid A-label');
      }
      if (digit > Math.floor((MAX_INT - i) / w)) {
        throw new IDNAError('Invalid A-label');
      }

      i += digit * w;
      const t = k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;
      if (digit < t) {
        break;
      }

      if (w > Math.floor(MAX_INT / (BASE - t))) {
        throw new IDNAError('Invalid A-label');
      }
      w *= BASE - t;
    }

    const outputLength = output.length + 1;
    bias = adapt(i - oldI, outputLength, oldI === 0);

    if (Math.floor(i / outputLength) > MAX_INT - n) {
      throw new IDNAError('Invalid A-label');
    }

    n += Math.floor(i / outputLength);
    i %= outputLength;

    if (n > 0x10ffff) {
      throw new IDNAError('Invalid A-label');
    }

    output.splice(i, 0, n);
    i += 1;
  }

  return String.fromCodePoint(...output);
}

