  const hasExtendedArabicIndic = chars.some((char) => isExtendedArabicIndicDigit(char.codePointAt(0)));
  const hasKanaOrHanContext = chars.some(
    (char) => char !== '\u30fb' && isKanaOrHanChar(char),
  );
  const hasRtlLetters = chars.some((char) => isRtlLetterChar(char));

  for (let index = 0; index < chars.length; index += 1) {
    const char = chars[index];
    const codePoint = char.codePointAt(0);
